const NATION_POOL: Record<string, string> = {
  GER: "GERMANIC", AUT: "GERMANIC", CHE: "GERMANIC",
  DEN: "DANISH", NOR: "NORWEGIAN", ISL: "ICELANDIC", FRO: "ICELANDIC",
  ESP: "IBERIAN", POR: "IBERIAN", ARG: "IBERIAN", BRA: "IBERIAN",
  FRA: "FRENCH", HUN: "HUNGARIAN", ROU: "HUNGARIAN",
  POL: "SLAVIC", HRV: "SLAVIC", SRB: "SLAVIC", SVN: "SLAVIC", BIH: "SLAVIC", MKD: "SLAVIC", MNE: "SLAVIC", CZE: "SLAVIC", SVK: "SLAVIC", LTU: "SLAVIC",
  ITA: "ITALIAN", NED: "DUTCH", BEL: "DUTCH",
  QAT: "ARABIC", DZA: "ARABIC", EGY: "ARABIC", TUN: "ARABIC", BHR: "ARABIC",
};

function pick(seedKey: string, list: readonly string[]): string {
  return list[Math.abs(seededOffset(seedKey, list.length * 7)) % list.length];
}

export function generateInternationalYouthName(seedKey: string, nation: string): { firstName: string; lastName: string } {
  const pool = POOLS[NATION_POOL[nation] ?? "GERMANIC"];
  return { firstName: pick(`${seedKey}:intl-first`, pool.first), lastName: pick(`${seedKey}:intl-last`, pool.last) };
}
